                        COMPLEMENT_TOKEN_NAME_POSTFIX
                    ),
                    makeTokenSymbol(
                        _derivativeSpecification.symbol(),
                        settlementDate,
                        COMPLEMENT_TOKEN_SYMBOL_POSTFIX
