function addRound(int256 _answer, uint256 _timestamp) external {
        rounds.push(StubFeedRound({ answer: _answer, timestamp: _timestamp }));
        latestRound_ = rounds.length;
    }

function updateUnderlyingValue(
        address _oracleIterator,
        address _oracle,
        uint256 _timestamp,
        uint256[] memory _roundHints
    ) public {
        require(_timestamp > 0, "Zero timestamp");
        require(_oracle != address(0), "Zero oracle");
        require(_oracleIterator != address(0), "Zero oracle iterator");

        IOracleIterator oracleIterator = IOracleIterator(_oracleIterator);
        underlyingValue = oracleIterator.getUnderlyingValue(
            _oracle,
            _timestamp,
            _roundHints
        );
    }

function getUnderlyingValue(
        address _oracle,
        uint256 _timestamp,
        uint256[] calldata _roundHints
    ) external view override returns (int256) {
        require(_timestamp > 0, "Zero timestamp");
        require(_oracle != address(0), "Zero oracle");
        require(_roundHints.length == 1, "Wrong number of hints");
        AggregatorV3Interface oracle = AggregatorV3Interface(_oracle);

        uint80 latestRoundId;
        (latestRoundId, , , , ) = oracle.latestRoundData();

        uint80 roundHint = uint80(_roundHints[0]);
        if (roundHint == 0) {
            return getIteratedAnswer(oracle, _timestamp, latestRoundId);
        }

        uint256 phaseId;
        (phaseId, ) = parseIds(latestRoundId);

        if (checkSamePhase(roundHint, phaseId)) {
            return
                getHintedAnswer(oracle, _timestamp, roundHint, latestRoundId);
        }

        int256 answer = getIteratedAnswer(oracle, _timestamp, latestRoundId);
        if (answer == NEGATIVE_INFINITY) {
            return
                getHintedAnswer(oracle, _timestamp, roundHint, latestRoundId);
        }
        return answer;
    }

function getHintedAnswer(
        AggregatorV3Interface _oracle,
        uint256 _timestamp,
        uint80 _roundHint,
        uint256 _latestRoundId
    ) internal view returns (int256) {
        int256 hintAnswer;
        uint256 hintTimestamp;
        (, hintAnswer, , hintTimestamp, ) = _oracle.getRoundData(_roundHint);

        require(
            hintTimestamp > 0 && hintTimestamp <= _timestamp,
            "Incorrect hint"
        );

        if (_roundHint + 1 > _latestRoundId) {
            return hintAnswer;
        }

        uint256 timestampNext;
        (, , , timestampNext, ) = _oracle.getRoundData(_roundHint + 1);
        if (timestampNext == 0 || timestampNext > _timestamp) {
            return hintAnswer;
        }

        return NEGATIVE_INFINITY;
    }

function getIteratedAnswer(
        AggregatorV3Interface _oracle,
        uint256 _timestamp,
        uint80 _latestRoundId
    ) internal view returns (int256) {
        uint256 roundTimestamp = 0;
        int256 roundAnswer = 0;
        uint80 roundId = _latestRoundId;

        for (uint256 i = 0; i < MAX_ITERATION; i++) {
            (, roundAnswer, , roundTimestamp, ) = _oracle.getRoundData(roundId);
            roundId = roundId - 1;
            if (roundTimestamp <= _timestamp) {
                return roundAnswer;
            }
            if (roundId == 0) {
                return NEGATIVE_INFINITY;
            }
        }

        return NEGATIVE_INFINITY;
    }

function parseIds(uint256 _roundId) internal pure returns (uint16, uint64) {
        uint16 phaseId = uint16(_roundId >> PHASE_OFFSET);
        uint64 aggregatorRoundId = uint64(_roundId);

        return (phaseId, aggregatorRoundId);
    }

function _check(bytes32 _key, address _value) internal virtual override {
        super._check(_key, _value);
        IDerivativeSpecification derivative = IDerivativeSpecification(_value);
        require(
            derivative.isDerivativeSpecification(),
            "Should be derivative specification"
        );

        bytes32 uniqueFieldsHash =
            keccak256(
                abi.encode(
                    derivative.oracleSymbols(),
                    derivative.oracleIteratorSymbols(),
                    derivative.collateralTokenSymbol(),
                    derivative.collateralSplitSymbol(),
                    derivative.livePeriod(),
                    derivative.primaryNominalValue(),
                    derivative.complementNominalValue(),
                    derivative.authorFee()
                )
            );

        require(!_uniqueFieldsHashMap[uniqueFieldsHash], "Same spec params");

        _uniqueFieldsHashMap[uniqueFieldsHash] = true;
    }

