function getRoundData(uint80 _roundId)
        public
        view
        virtual
        override
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        )
    {
        (uint16 phaseId, uint64 aggregatorRoundId) = parseIds(_roundId);

        (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 ansIn
        ) = phaseAggregators[phaseId].getRoundData(aggregatorRoundId);

        return
            addPhaseIds(roundId, answer, startedAt, updatedAt, ansIn, phaseId);
    }

