function passesTest(address wallet) external view override returns (bool) {
    uint256[] memory _userNFTTokenIds = distributor.getBoostNfts(wallet);
    return wallet == address(0) ? false : _userNFTTokenIds.length >= 1;
  }

function getMultiplier(address wallet)
    external
    view
    override
    returns (uint256)
  {
    if (wallet == address(0)) return 0;

    uint256 _userOKLGBalance = distributor.getShares(wallet);
    if (_userOKLGBalance == 0) return 0;

    uint256[] memory _userNFTTokenIds = distributor.getBoostNfts(wallet);
    uint256 _userNFTBalance = _userNFTTokenIds.length;
    if (_userNFTBalance == 0) return 0;

    for (uint256 _i = 0; _i < multipliers.length; _i++) {
      Booster memory mult = multipliers[_i];
      if (_userOKLGBalance > mult.maxOKLGBalance) continue;

      uint256 nftBalanceAdjusted = _userNFTBalance > mult.maxNFTBalance
        ? mult.maxNFTBalance
        : _userNFTBalance;
      return mult.baseBoost.mul(nftBalanceAdjusted);
    }
    return 0;
  }

function setAllMultipliers(Booster[] memory _boosters) external onlyOwner {
    delete multipliers;
    for (uint256 _i = 0; _i < _boosters.length; _i++) {
      multipliers.push(_boosters[_i]);
    }
  }

function getLatestETHPrice() public view returns (uint256) {
    uint8 decimals = priceFeed.decimals();
    (, int256 price, , , ) = priceFeed.latestRoundData();
    return uint256(price) * (10**18 / 10**decimals);
  }

function buyTokens(address _to) crowdfundIsActive nonZeroAddress(_to) payable {
        uint256 weiAmount = msg.value;
        uint256 tokens = weiAmount * getIcoPrice();
        weiRaised = weiRaised.add(weiAmount);
        wallet.transfer(weiAmount);
        if (!token.transferFromCrowdfund(_to, tokens)) {
            revert();
        }
        TokenPurchase(_to, weiAmount, tokens);
    }

function closeCrowdfund() external onlyOwner returns (bool success) {
        AmountRaised(wallet, weiRaised);
        token.finalizeCrowdfund();
        return true;
    }

function getIcoPrice() public constant returns (uint price) {
        if (now > (startsAt + 3 weeks)) {
           return 1275; // week 4
        } else if (now > (startsAt + 2 weeks)) {
           return 1700; // week 3
        } else if (now > (startsAt + 1 weeks)) {
           return 2250; // week 2
        } else {
           return 3000; // week 1
        }
    }

function supplyTokenTo(uint256 _amount, address to) override external {
        uint256 shares = _tokenToShares(_amount);

        _mint(to, shares);

        // NOTE: we have to deposit after calculating shares to mint
        token.safeTransferFrom(msg.sender, address(this), _amount);

        _depositInVault();

        emit SuppliedTokenTo(msg.sender, shares, _amount, to);
    }

function redeemToken(uint256 amount) external override returns (uint256) {
        uint256 shares = _tokenToShares(amount);

        uint256 withdrawnAmount = _withdrawFromVault(amount);

        _burn(msg.sender, shares);

        token.safeTransfer(msg.sender, withdrawnAmount);

        emit RedeemedToken(msg.sender, shares, amount);
        return withdrawnAmount;
    }

function initialize(
        IYVaultV2 _vault,
        IERC20Upgradeable _token
    ) 
        public 
        initializer
    {
        require(address(vault) == address(0), "!already initialized");
        require(_vault.token() == address(_token), "!incorrect vault");
        require(_vault.activation() != uint256(0), "!vault not initialized");
        // NOTE: Vaults from 0.3.2 to 0.3.4 have dips in shareValue
        require(!areEqualStrings(_vault.apiVersion(), "0.3.2"), "!vault not compatible");
        require(!areEqualStrings(_vault.apiVersion(), "0.3.3"), "!vault not compatible");
        require(!areEqualStrings(_vault.apiVersion(), "0.3.4"), "!vault not compatible");

        vault = _vault;
        token = _token;

        __Ownable_init();

        _token.safeApprove(address(vault), type(uint256).max);

        emit YieldSourceYearnV2Initialized(
            _vault,
            _token
        );
    }

function sponsor(uint256 amount) external {
        token.safeTransferFrom(msg.sender, address(this), amount);

        _depositInVault();

        emit Sponsored(msg.sender, amount);
    }

function _depositInVault() internal returns (uint256) {
        IYVaultV2 v = vault; // NOTE: for gas usage
        if(token.allowance(address(this), address(v)) < token.balanceOf(address(this))) {
            token.safeApprove(address(v), 0);
            token.safeApprove(address(v), type(uint256).max);
        }
        // this will deposit full balance (for cases like not enough room in Vault)
        return v.deposit();
    }

function _withdrawFromVault(uint amount) internal returns (uint256) {
        uint256 yShares = _tokenToYShares(amount);
        uint256 previousBalance = token.balanceOf(address(this));
        // we accept losses to avoid being locked in the Vault (if losses happened for some reason)
        if(maxLosses != 0) {
            vault.withdraw(yShares, address(this), maxLosses);
        } else {
            vault.withdraw(yShares);
        }
        uint256 currentBalance = token.balanceOf(address(this));

        return previousBalance.sub(currentBalance);
    }

function _balanceOfYShares() internal view returns (uint256) {
        return vault.balanceOf(address(this));
    }

