function convert(
        AztecTypes.AztecAsset calldata inputAssetA,
        AztecTypes.AztecAsset calldata,
        AztecTypes.AztecAsset calldata outputAssetA,
        AztecTypes.AztecAsset calldata,
        uint256 inputValue,
        uint256 interactionNonce,
        uint64 auxData,
        address rollupBeneficiary
    )
        external
        payable
        override
        returns (
            uint256 outputValueA,
            uint256,
            bool isAsync
        )
    {
        // Only Rollup Processor can call this function
        require(
            msg.sender == rollupProcessor,
            "IssuanceBridge: INVALID_CALLER"
        );
        require(inputValue > 0, "IssuanceBridge: INVALID_INPUT_VALUE");

        isAsync = false;

        // -----------------------------------------------------------------------------------------
        // Check if the user wants to ISSUE or REDEEM SetToken based on the input/output asset types
        // -----------------------------------------------------------------------------------------

        // REDEEM SET: User wants to redeem SetToken and receive ETH or ERC20
        // inputAssetA: SetToken
        // outputAssetA ERC20 or ETH
        if (
            setController.isSet(address(inputAssetA.erc20Address)) &&
            (outputAssetA.assetType == AztecTypes.AztecAssetType.ETH ||
                outputAssetA.assetType == AztecTypes.AztecAssetType.ERC20)
        ) {
            // Check that spending of the given SetToken is approved
            require(
                IERC20(inputAssetA.erc20Address).approve(
                    address(exchangeIssuance),
                    inputValue
                ),
                "IssuanceBridge: APPROVE_FAILED"
            );

            // user wants to receive ETH
            if (outputAssetA.assetType == AztecTypes.AztecAssetType.ETH) {
                outputValueA = exchangeIssuance.redeemExactSetForETH(
                    ISetToken(address(inputAssetA.erc20Address)),
                    inputValue, // _amountSetToken
                    0 // __minEthOut
                );
                // Send ETH to rollup processor
                IRollupProcessor(rollupProcessor).receiveEthFromBridge{value: outputValueA}(interactionNonce);
            }

            // user wants to receive ERC20
            if (outputAssetA.assetType == AztecTypes.AztecAssetType.ERC20) {
                outputValueA = exchangeIssuance.redeemExactSetForToken(
                    ISetToken(address(inputAssetA.erc20Address)), // _setToken,
                    IERC20(address(outputAssetA.erc20Address)), // _outputToken,
                    inputValue, //  _amountSetToken,
                    0 //  _minOutputReceive
                );

                // approve the transfer of funds back to the rollup contract
                require(
                    IERC20(outputAssetA.erc20Address).approve(
                        rollupProcessor,
                        outputValueA
                    ),
                    "IssuanceBridge: APPROVE_FAILED"
                );
            }
        }
        // ISSUE SET: User wants to issue SetToken in for ERC20
        // inputAssetA: ERC20 (but not SetToken)
        // outputAssetA: SetToken
        else if (
            inputAssetA.assetType == AztecTypes.AztecAssetType.ERC20 &&
            !setController.isSet(address(inputAssetA.erc20Address)) &&
            setController.isSet(address(outputAssetA.erc20Address))
        ) {
            // Check that spending of the ERC20 is approved
            require(
                IERC20(inputAssetA.erc20Address).approve(
                    address(exchangeIssuance),
                    inputValue
                ),
                "IssuanceBridge: APPROVE_FAILED"
            );

            outputValueA = exchangeIssuance.issueSetForExactToken(
                ISetToken(address(outputAssetA.erc20Address)),
                IERC20(address(inputAssetA.erc20Address)),
                inputValue, //  _amountInput
                0 // _minSetReceive
            );

            // approve the transfer of funds back to the rollup contract
            require(
                IERC20(outputAssetA.erc20Address).approve(
                    rollupProcessor,
                    outputValueA
                ),
                "IssuanceBridge: APPROVE_FAILED"
            );
        }
        // ISSUE: User wants to issue SetToken for ETH
        // inputAssetA: ETH
        // outputAssetA: SetToken
        else if (
            inputAssetA.assetType == AztecTypes.AztecAssetType.ETH &&
            setController.isSet(address(outputAssetA.erc20Address))
        ) {
            // issue SetTokens for a given amount of ETH (=inputValue)
            outputValueA = exchangeIssuance.issueSetForExactETH{
                value: inputValue
            }(
                ISetToken(address(outputAssetA.erc20Address)),
                0 // _minSetReceive
            );

            // approve the transfer of funds back to the rollup contract
            require(
                IERC20(outputAssetA.erc20Address).approve(
                    rollupProcessor,
                    outputValueA
                ),
                "IssuanceBridge: APPROVE_FAILED"
            );
        } else {
            revert("IssuanceBridge: INCOMPATIBLE_ASSET_PAIR");
        }
    }

function setUnderlyingToZkAToken(address underlyingAsset) external {
        IPool pool = IPool(addressesProvider.getLendingPool());

        IERC20Detailed aToken = IERC20Detailed(
            pool.getReserveData(underlyingAsset).aTokenAddress
        );

        require(
            address(aToken) != address(0),
            "AaveLendingBridge: NO_LENDING_POOL"
        );
        require(
            underlyingToZkAToken[underlyingAsset] == address(0),
            "AaveLendingBridge: ZK_TOKEN_SET"
        );

        // TODO add AztecAAVEBridge token to name / symbol
        underlyingToZkAToken[underlyingAsset] = address(
            new ZkAToken(aToken.name(), aToken.symbol(), aToken.decimals())
        );
    }

function _enter(address inputAsset, uint256 amount)
        internal
        returns (uint256)
    {
        IPool pool = IPool(addressesProvider.getLendingPool());
        IScaledBalanceToken aToken = IScaledBalanceToken(
            pool.getReserveData(inputAsset).aTokenAddress
        );
        require(
            address(aToken) != address(0),
            "AaveLendingBridge: NO_LENDING_POOL"
        );
        require(
            underlyingToZkAToken[inputAsset] != address(0),
            "AaveLendingBridge: NO_ZK_TOKEN_POOL"
        );

        // 1. Read the scaled balance from the lending pool
        uint256 scaledBalance = aToken.scaledBalanceOf(address(this));

        // 2. Approve totalInputValue to be lent on AAVE
        IERC20Detailed(inputAsset).approve(address(pool), amount);

        // 3. Lend totalInputValue of inputAssetA on AAVE lending pool
        pool.deposit(inputAsset, amount, address(this), 0);

        // 4. Mint the difference between the scaled balance at the start of the interaction and after the deposit as our zkAToken
        uint256 diff = aToken.scaledBalanceOf(address(this)).sub(scaledBalance);
        IERC20Detailed(underlyingToZkAToken[inputAsset]).mint(
            address(this),
            diff
        );

        IERC20Detailed(underlyingToZkAToken[inputAsset]).approve(
            rollupProcessor,
            diff
        );
        return diff;
    }

function _exit(address outputAsset, uint256 scaledAmount)
        internal
        returns (uint256)
    {
        IPool pool = IPool(addressesProvider.getLendingPool());
        IERC20 aToken = IERC20(pool.getReserveData(outputAsset).aTokenAddress);

        // 1. Compute the amount from the scaledAmount supplied
        uint256 underlyingAmount = scaledAmount.rayMul(
            pool.getReserveNormalizedIncome(outputAsset)
        );

        // 2. Lend totalInputValue of inputAssetA on AAVE lending pool and return the amount of tokens
        uint256 outputValue = pool.withdraw(
            outputAsset,
            underlyingAmount,
            address(this)
        );

        IERC20Detailed(outputAsset).approve(rollupProcessor, outputValue);

        // 3. Burn the supplied amount of zkAToken as this has now been withdrawn
        IZkAToken(underlyingToZkAToken[outputAsset]).burn(scaledAmount);

        return outputValue;
    }

function convert(
    AztecTypes.AztecAsset calldata inputAssetA,
    AztecTypes.AztecAsset calldata,
    AztecTypes.AztecAsset calldata outputAssetA,
    AztecTypes.AztecAsset calldata,
    uint256 totalInputValue,
    uint256 interactionNonce,
    uint64 auxData,
    address rollupBeneficiary
  )
    external
    payable
    returns (
      uint256 outputValueA,
      uint256 outputValueB,
      bool isAsync
    )
  {
    // ### INITIALIZATION AND SANITY CHECKS
    require(msg.sender == rollupProcessor, "MStableBridge: INVALID_CALLER");

    require(
      inputAssetA.id != outputAssetA.id,
      "MStableBridge: ASSET_IDS_EQUAL"
    );

    require(
      inputAssetA.assetType == AztecTypes.AztecAssetType.ERC20,
      "MStableBridge: NOT_ERC20"
    );
    // operation is asynchronous
    isAsync = false;

    address mUSD = address(0xe2f2a5C287993345a840Db3B0845fbC70f5935a5);
    address imUSD = address(0x30647a72Dc82d7Fbb1123EA74716aB8A317Eac19);
    address dai = address(0x6B175474E89094C44Da98b954EedeAC495271d0F);

    if (outputAssetA.erc20Address == imUSD) {
      ERC20(inputAssetA.erc20Address).approve(
        address(mUSD),
        totalInputValue
      );

      uint256 minimumMUSDToMint = totalInputValue * ((uint256(10000) - uint256(auxData)))/10000;
      uint256 massetsMinted = IMStableAsset(mUSD).mint(dai, totalInputValue, minimumMUSDToMint, address(this)); // Minting

      ERC20(mUSD).approve(
        imUSD,
        massetsMinted
      );

      outputValueA = IMStableSavingsContract(imUSD).depositSavings(massetsMinted); // Deposit into save

      ERC20(imUSD).approve(
        rollupProcessor,
        outputValueA
      );
    } else {
        uint256 redeemedMUSD = IMStableSavingsContract(imUSD).redeemCredits(totalInputValue);
        uint256 minimumBAssetToRedeem = redeemedMUSD * ((uint256(10000) - uint256(auxData)))/10000;
        uint256 redeemedValue = IMStableAsset(mUSD).redeem(dai, redeemedMUSD, minimumBAssetToRedeem, address(this));
        outputValueA = redeemedValue;
        ERC20(dai).approve(
          rollupProcessor,
          outputValueA
        );
    }
  }

function convert(
    AztecTypes.AztecAsset memory inputAssetA,
    AztecTypes.AztecAsset memory inputAssetB,
    AztecTypes.AztecAsset memory outputAssetA,
    AztecTypes.AztecAsset memory outputAssetB,
    uint256 totalInputValue,
    uint256 interactionNonce,
    uint64 auxData,
    address
  )
    external
    payable
    returns (
      uint256 outputValueA,
      uint256 outputValueB,
      bool isAsync
    )
  {
    // ### INITIALIZATION AND SANITY CHECKS
    require(msg.sender == rollupProcessor, "RaiBridge: INVALID_CALLER");

    if (inputAssetA.assetType == AztecTypes.AztecAssetType.ETH) {
        // transfer to weth
        IWETH(WETH).deposit{value: msg.value}();
    }


    if (isInitialized) {
      (uint collateralRatio, uint raiToEth, ISafeEngine.SAFE memory safe) = getSafeData();
      if (outputAssetA.assetType == AztecTypes.AztecAssetType.ERC20 && outputAssetA.erc20Address == RAI) {
        require(outputAssetB.assetType == AztecTypes.AztecAssetType.ERC20 && outputAssetB.erc20Address == address(this));
            // deposit weth output RAI
            outputValueA = _addCollateral(totalInputValue, collateralRatio, raiToEth);
            outputValueB = outputValueA;
            _mint(address(this), outputValueB);
        } else if (inputAssetA.assetType == AztecTypes.AztecAssetType.ERC20 && inputAssetA.erc20Address == RAI) {
          _burn(address(this), totalInputValue);
            // deposit RAI output weth
            outputValueA = _removeCollateral(totalInputValue, safe);
            if (outputAssetA.assetType == AztecTypes.AztecAssetType.ETH) {
              // change weth to eth
              IWETH(WETH).withdraw(outputValueA);
              IRollupProcessor(rollupProcessor).receiveEthFromBridge{value: outputValueA}(interactionNonce);
          }
        }
    } else {
        // CONTRACT INITIALIZATION
        require(auxData > 0, "no collateral ratio provided");
        require(outputAssetB.assetType == AztecTypes.AztecAssetType.ERC20 && outputAssetB.erc20Address == address(this));
        isInitialized = true;

        require(IERC20(address(this)).approve(rollupProcessor, type(uint).max), "BridgeTokens approve failed");

        (, int raiToEth, , ,) = priceFeed.latestRoundData();

        // minimum amount of RAI to be borrowed at initialization is 1469 RAI
        // please provide enough ETH/WETH for that or this method will revert
        outputValueA = _addCollateral(totalInputValue, auxData, uint(raiToEth));
        outputValueB = outputValueA;
        _mint(address(this), outputValueB);
    }
  }

function getSafeData() public view returns (uint256 collateralRatio, uint raiToEth, ISafeEngine.SAFE memory safe) {
    safe = ISafeEngine(SAFE_ENGINE).safes(0x4554482d41000000000000000000000000000000000000000000000000000000, SAFE_HANDLER);
     // rai to Eth Ratio
    (, int x, , ,) = priceFeed.latestRoundData();
    raiToEth = uint(x);
    if (safe.lockedCollateral != 0 || safe.generatedDebt != 0) {
      collateralRatio =  safe.lockedCollateral.mul(1e22).div(raiToEth).div(safe.generatedDebt);
    } else {
      collateralRatio = 0;
    }
  }

function _addCollateral(uint _wethAmount, uint _collateralRatio, uint _raiToEth) internal returns (uint outputRai) {
      IEthJoin(ETH_JOIN).join(SAFE_HANDLER, _wethAmount);

      // expected RAI amount = eth_amount * (1e18/raiToEthPrice) * (1/collateralRatio)
      outputRai = _wethAmount.mul(1e22).div(_raiToEth).div(_collateralRatio);

      ISafeManager(SAFE_MANAGER).modifySAFECollateralization(safeId, int(_wethAmount), int(outputRai));

      ISafeManager(SAFE_MANAGER).transferInternalCoins(safeId, address(this), outputRai * 10**27);

      ICoinJoin(COIN_JOIN).exit(address(this), outputRai);
  }

function _removeCollateral(uint _raiAmount, ISafeEngine.SAFE memory safe) internal returns (uint outputWeth) {
        ICoinJoin(COIN_JOIN).join(SAFE_HANDLER, _raiAmount);

        outputWeth = safe.lockedCollateral.mul(_raiAmount).div(safe.generatedDebt);

        ISafeManager(SAFE_MANAGER).modifySAFECollateralization(safeId, -int(outputWeth), -int(_raiAmount));
        ISafeManager(SAFE_MANAGER).transferCollateral(safeId, address(this), outputWeth);
        IEthJoin(ETH_JOIN).exit(address(this), outputWeth);
  }

function addPosition(address pos, uint8 version) external onlyOwner {
    require(positions[pos].version == 0, 'already added');
    require(version > 0, 'version < 1');
    IHypervisor(pos).token0().approve(pos, MAX_INT);
    IHypervisor(pos).token1().approve(pos, MAX_INT);
    Position storage p = positions[pos];
    p.version = version;
  }

function deposit(
    uint256 deposit0,
    uint256 deposit1,
    address to,
    address from,
    address pos
  ) external returns (uint256 shares) {
    require(positions[pos].version != 0, 'not added');
    // SWC-107-Reentrancy: L75-82
    if (twapCheck || positions[pos].twapOverride) {
      // check twap
      checkPriceChange(
        pos,
        (positions[pos].twapOverride ? positions[pos].twapInterval : twapInterval),
        (positions[pos].twapOverride ? positions[pos].priceThreshold : priceThreshold)
      );
    }

    if (!freeDeposit && !positions[pos].list[msg.sender] && !positions[pos].freeDeposit) {
      // freeDeposit off and hypervisor msg.sender not on list
      require(properDepositRatio(pos, deposit0, deposit1), "Improper ratio");
    }

    if (positions[pos].depositOverride) {
      if (positions[pos].deposit0Max > 0) {
        require(deposit0 <= positions[pos].deposit0Max, "token0 exceeds");
      }
      if (positions[pos].deposit1Max > 0) {
        require(deposit1 <= positions[pos].deposit1Max, "token1 exceeds");
      }
    }

    if (positions[pos].version < 3) {
      // requires asset transfer to proxy
      if (deposit0 != 0) {
        IHypervisor(pos).token0().transferFrom(msg.sender, address(this), deposit0);
      }
      if (deposit1 != 0) {
        IHypervisor(pos).token1().transferFrom(msg.sender, address(this), deposit1);
      }
      if (positions[pos].version < 2) {
        // requires lp token transfer from proxy to msg.sender
        shares = IHypervisor(pos).deposit(deposit0, deposit1, address(this));
        IHypervisor(pos).transfer(to, shares);
      }
      else{
        // transfer lp tokens direct to msg.sender
        shares = IHypervisor(pos).deposit(deposit0, deposit1, msg.sender);
      }
    }
    else {
      // transfer lp tokens direct to msg.sender
      shares = IHypervisor(pos).deposit(deposit0, deposit1, msg.sender, msg.sender);
    }

    if (positions[pos].depositOverride) {
      require(IHypervisor(pos).totalSupply() <= positions[pos].maxTotalSupply, "supply exceeds");
    }

  }

function depositSwap(
    int256 swapAmount, // (-) token1, (+) token0 for token1; amount to swap
    uint256 deposit0,
    uint256 deposit1,
    address to,
    address from,
    bytes memory path,
    address pos,
    address _router
  ) external returns (uint256 shares) {

    if (twapCheck || positions[pos].twapOverride) {
      // check twap
      checkPriceChange(
        pos,
        (positions[pos].twapOverride ? positions[pos].twapInterval : twapInterval),
        (positions[pos].twapOverride ? positions[pos].priceThreshold : priceThreshold)
      );
    }

    if (!freeDeposit && !positions[pos].list[msg.sender] && !positions[pos].freeDeposit) {
      // freeDeposit off and hypervisor msg.sender not on list
      require(properDepositRatio(pos, deposit0, deposit1), "Improper ratio");
    }

    if (positions[pos].depositOverride) {
      if (positions[pos].deposit0Max > 0) {
        require(deposit0 <= positions[pos].deposit0Max, "token0 exceeds");
      }
      if (positions[pos].deposit1Max > 0) {
        require(deposit1 <= positions[pos].deposit1Max, "token1 exceeds");
      }
    }

    router = ISwapRouter(_router);
    uint256 amountOut;
    uint256 swap;
    if(swapAmount < 0) {
        //swap token1 for token0

        swap = uint256(swapAmount * -1);
        IHypervisor(pos).token1().transferFrom(msg.sender, address(this), deposit1+swap);
        amountOut = router.exactInput(
            ISwapRouter.ExactInputParams(
                path,
                address(this),
                block.timestamp + swapLife,
                swap,
                deposit0
            )
        );
    }
    else{
        //swap token1 for token0
        swap = uint256(swapAmount);
        IHypervisor(pos).token0().transferFrom(msg.sender, address(this), deposit0+swap);

        amountOut = router.exactInput(
            ISwapRouter.ExactInputParams(
                path,
                address(this),
                block.timestamp + swapLife,
                swap,
                deposit1
            )
        );      
    }

    require(amountOut > 0, "Swap failed");

    if (positions[pos].version < 2) {
      // requires lp token transfer from proxy to msg.sender 
      shares = IHypervisor(pos).deposit(deposit0, deposit1, address(this));
      IHypervisor(pos).transfer(to, shares);
    }
    else{
      // transfer lp tokens direct to msg.sender 
      shares = IHypervisor(pos).deposit(deposit0, deposit1, msg.sender);
    }

    if (positions[pos].depositOverride) {
      require(IHypervisor(pos).totalSupply() <= positions[pos].maxTotalSupply, "supply exceeds");
    }
  }

function getDepositAmount(
    address pos,
    address token,
    uint256 deposit
  ) public view returns (uint256 amountStart, uint256 amountEnd) {
    require(token == address(IHypervisor(pos).token0()) || token == address(IHypervisor(pos).token1()), "token mistmatch");
    require(deposit > 0, "deposits can't be zero");
    (uint256 total0, uint256 total1) = IHypervisor(pos).getTotalAmounts();
    if (IHypervisor(pos).totalSupply() == 0 || total0 == 0 || total1 == 0) return (0, 0);

    uint256 ratioStart = total0.mul(1e18).div(total1).mul(depositDelta).div(deltaScale);
    uint256 ratioEnd = total0.mul(1e18).div(total1).div(depositDelta).mul(deltaScale);

    if (token == address(IHypervisor(pos).token0())) {
      return (deposit.mul(1e18).div(ratioStart), deposit.mul(1e18).div(ratioEnd));
    }
    return (deposit.mul(ratioStart).div(1e18), deposit.mul(ratioEnd).div(1e18));
  }

function properDepositRatio(
    address pos,
    uint256 deposit0,
    uint256 deposit1
  ) public view returns (bool) {
    (uint256 hype0, uint256 hype1) = IHypervisor(pos).getTotalAmounts();
    if (IHypervisor(pos).totalSupply() != 0) {
      uint256 depositRatio = deposit0 == 0 ? 10e18 : deposit1.mul(1e18).div(deposit0);
      depositRatio = depositRatio > 10e18 ? 10e18 : depositRatio;
      depositRatio = depositRatio < 10e16 ? 10e16 : depositRatio;
      uint256 hypeRatio = hype0 == 0 ? 10e18 : hype1.mul(1e18).div(hype0);
      hypeRatio = hypeRatio > 10e18 ? 10e18 : hypeRatio;
      hypeRatio = hypeRatio < 10e16 ? 10e16 : hypeRatio;
      return (FullMath.mulDiv(depositRatio, deltaScale, hypeRatio) < depositDelta &&
              FullMath.mulDiv(hypeRatio, deltaScale, depositRatio) < depositDelta);
    }
    return true;
  }

function swap(
        address token,
        bytes memory path,
        bool send
    ) external onlyOwner {
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (IERC20(token).allowance(address(this), address(router)) < balance) IERC20(token).approve(address(router), balance);
        uint256 amountOut = router.exactInput(
            ISwapRouter.ExactInputParams(
                path,
                send ? recipient : address(this),
                block.timestamp + 10000,
                balance,
                0
            )
        );
        emit SwapVISR(token, send ? recipient : address(this), amountOut);
    }

function sendToken(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(recipient, amount);
    }

function withdraw(
        uint256 shares,
        address to,
        address from
    ) external override returns (uint256 amount0, uint256 amount1) {
        require(shares > 0, "shares");
        require(to != address(0), "to");

        // Withdraw liquidity from Uniswap pool
        (uint256 base0, uint256 base1) = _burnLiquidity(
            baseLower,
            baseUpper,
            _liquidityForShares(baseLower, baseUpper, shares),
            to,
            false
        );
        (uint256 limit0, uint256 limit1) = _burnLiquidity(
            limitLower,
            limitUpper,
            _liquidityForShares(limitLower, limitUpper, shares),
            to,
            false
        );

        // Push tokens proportional to unused balances
        uint256 totalSupply = totalSupply();
        uint256 unusedAmount0 = token0.balanceOf(address(this)).mul(shares).div(totalSupply);
        uint256 unusedAmount1 = token1.balanceOf(address(this)).mul(shares).div(totalSupply);
        if (unusedAmount0 > 0) token0.safeTransfer(to, unusedAmount0);
        if (unusedAmount1 > 0) token1.safeTransfer(to, unusedAmount1);

        amount0 = base0.add(limit0).add(unusedAmount0);
        amount1 = base1.add(limit1).add(unusedAmount1);

        require(
            from == msg.sender || IUniversalVault(from).owner() == msg.sender,
            "Sender must own the tokens"
        );
        _burn(from, shares);

        emit Withdraw(from, to, shares, amount0, amount1);
    }

function rebalance(
        int24 _baseLower,
        int24 _baseUpper,
        int24 _limitLower,
        int24 _limitUpper,
        address feeRecipient,
        int256 swapQuantity
    ) external override onlyOwner {
        require(
            _baseLower < _baseUpper &&
                _baseLower % tickSpacing == 0 &&
                _baseUpper % tickSpacing == 0,
            "base position invalid"
        );
        require(
            _limitLower < _limitUpper &&
                _limitLower % tickSpacing == 0 &&
                _limitUpper % tickSpacing == 0,
            "limit position invalid"
        );

        // update fees
        (uint128 baseLiquidity, , ) = _position(baseLower, baseUpper);
        if (baseLiquidity > 0) {
            pool.burn(baseLower, baseUpper, 0);
        }
        (uint128 limitLiquidity, , ) = _position(limitLower, limitUpper);
        if (limitLiquidity > 0) {
            pool.burn(limitLower, limitUpper, 0);
        }

        // Withdraw all liquidity and collect all fees from Uniswap pool
        (, uint256 feesLimit0, uint256 feesLimit1) = _position(baseLower, baseUpper);
        (, uint256 feesBase0, uint256 feesBase1) = _position(limitLower, limitUpper);

        uint256 fees0 = feesBase0.add(feesLimit0);
        uint256 fees1 = feesBase1.add(feesLimit1);
        _burnLiquidity(baseLower, baseUpper, baseLiquidity, address(this), true);
        _burnLiquidity(limitLower, limitUpper, limitLiquidity, address(this), true);

        // transfer 10% of fees for VISR buybacks
        if (fees0 > 0) token0.safeTransfer(feeRecipient, fees0.div(10));
        if (fees1 > 0) token1.safeTransfer(feeRecipient, fees1.div(10));

        emit Rebalance(
            currentTick(),
            token0.balanceOf(address(this)),
            token1.balanceOf(address(this)),
            fees0,
            fees1,
            totalSupply()
        );

        // swap tokens if required
        if (swapQuantity != 0) {
            pool.swap(
                address(this),
                swapQuantity > 0,
                swapQuantity > 0 ? swapQuantity : -swapQuantity,
                swapQuantity > 0 ? TickMath.MIN_SQRT_RATIO + 1 : TickMath.MAX_SQRT_RATIO - 1,
                abi.encode(address(this))
            );
        }

        baseLower = _baseLower;
        baseUpper = _baseUpper;
        baseLiquidity = _liquidityForAmounts(
            baseLower,
            baseUpper,
            token0.balanceOf(address(this)),
            token1.balanceOf(address(this))
        );
        _mintLiquidity(baseLower, baseUpper, baseLiquidity, address(this));

        limitLower = _limitLower;
        limitUpper = _limitUpper;
        limitLiquidity = _liquidityForAmounts(
            limitLower,
            limitUpper,
            token0.balanceOf(address(this)),
            token1.balanceOf(address(this))
        );
        _mintLiquidity(limitLower, limitUpper, limitLiquidity, address(this));
    }

function getTotalAmounts() public view override returns (uint256 total0, uint256 total1) {
        (, uint256 base0, uint256 base1) = getBasePosition();
        (, uint256 limit0, uint256 limit1) = getLimitPosition();
        total0 = token0.balanceOf(address(this)).add(base0).add(limit0);
        total1 = token1.balanceOf(address(this)).add(base1).add(limit1);
    }

function pendingFees() external onlyOwner returns (uint256 fees0, uint256 fees1) {
        // update fees
        (uint128 baseLiquidity, , ) = _position(baseLower, baseUpper);
        if (baseLiquidity > 0) {
            pool.burn(baseLower, baseUpper, 0);
        }
        (uint128 limitLiquidity, , ) = _position(limitLower, limitUpper);
        if (limitLiquidity > 0) {
            pool.burn(limitLower, limitUpper, 0);
        }

        // Withdraw all liquidity and collect all fees from Uniswap pool
        (, uint256 feesLimit0, uint256 feesLimit1) = _position(baseLower, baseUpper);
        (, uint256 feesBase0, uint256 feesBase1) = _position(limitLower, limitUpper);

        fees0 = feesBase0.add(feesLimit0);
        fees1 = feesBase1.add(feesLimit1);
    }

function addBaseLiquidity(uint256 amount0, uint256 amount1) external onlyOwner {
        uint128 baseLiquidity = _liquidityForAmounts(
            baseLower,
            baseUpper,
            amount0 == 0 && amount1 == 0 ? token0.balanceOf(address(this)) : amount0,
            amount0 == 0 && amount1 == 0 ? token1.balanceOf(address(this)) : amount1
        );
        _mintLiquidity(baseLower, baseUpper, baseLiquidity, address(this));
    }

function addLimitLiquidity(uint256 amount0, uint256 amount1) external onlyOwner {
        uint128 limitLiquidity = _liquidityForAmounts(
            limitLower,
            limitUpper,
            amount0 == 0 && amount1 == 0 ? token0.balanceOf(address(this)) : amount0,
            amount0 == 0 && amount1 == 0 ? token1.balanceOf(address(this)) : amount1
        );
        _mintLiquidity(limitLower, limitUpper, limitLiquidity, address(this));
    }

function _mintLiquidity(
        int24 tickLower,
        int24 tickUpper,
        uint128 liquidity,
        address payer
    ) internal returns (uint256 amount0, uint256 amount1) {
        if (liquidity > 0) {
            (amount0, amount1) = pool.mint(
                address(this),
                tickLower,
                tickUpper,
                liquidity,
                abi.encode(payer)
            );
        }
    }

function _burnLiquidity(
        int24 tickLower,
        int24 tickUpper,
        uint128 liquidity,
        address to,
        bool collectAll
    ) internal returns (uint256 amount0, uint256 amount1) {
        if (liquidity > 0) {
            // Burn liquidity
            (uint256 owed0, uint256 owed1) = pool.burn(tickLower, tickUpper, liquidity);

            // Collect amount owed
            uint128 collect0 = collectAll ? type(uint128).max : _uint128Safe(owed0);
            uint128 collect1 = collectAll ? type(uint128).max : _uint128Safe(owed1);
            if (collect0 > 0 || collect1 > 0) {
                (amount0, amount1) = pool.collect(to, tickLower, tickUpper, collect0, collect1);
            }
        }
    }

function _position(int24 tickLower, int24 tickUpper)
        internal
        view
        returns (
            uint128 liquidity,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        )
    {
        bytes32 positionKey = keccak256(abi.encodePacked(address(this), tickLower, tickUpper));
        (liquidity, , , tokensOwed0, tokensOwed1) = pool.positions(positionKey);
    }

function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external override {
        require(msg.sender == address(pool));
        address payer = abi.decode(data, (address));

        if (amount0Delta > 0) {
            if (payer == address(this)) {
                token0.safeTransfer(msg.sender, uint256(amount0Delta));
            } else {
                token0.safeTransferFrom(payer, msg.sender, uint256(amount0Delta));
            }
        } else if (amount1Delta > 0) {
            if (payer == address(this)) {
                token1.safeTransfer(msg.sender, uint256(amount1Delta));
            } else {
                token1.safeTransferFrom(payer, msg.sender, uint256(amount1Delta));
            }
        }
    }

function _amountsForLiquidity(
        int24 tickLower,
        int24 tickUpper,
        uint128 liquidity
    ) internal view returns (uint256, uint256) {
        (uint160 sqrtRatioX96, , , , , , ) = pool.slot0();
        return
